export const phy2Tasks={"power": [{"id": "compare", "title": "Explain the evidence", "kind": "power", "type": "compare", "cases": [["0", "Power describes…", ["Energy transferred per second", "Total stored energy alone", "Force multiplied by mass"], 0, "Power is a rate, measured in watts."], ["1", "120 J in 2 s gives…", ["240 W", "60 W", "0.0167 W"], 1, "Divide energy by time."], ["2", "Two motors each do 120 J; the quicker one has…", ["Greater work by definition", "Less energy transferred in total", "Greater power, equal work"], 2, "Compare equal work over different times."]]}, {"id": "calculate", "title": "Calculate with units", "kind": "power-data", "type": "numeric", "prompt": "Fresh motor does 240 J in 8 s. Calculate power.", "answer": 30, "unit": "W", "reasonChoices": ["240÷8", "240×8", "8÷240"], "reason": 0, "why": "Check the equation, order and supplied units."}, {"id": "model", "title": "Predict and compare the model", "kind": "power-model", "type": "experiment", "experiment": "power", "why": "Predict from the stated quantities; record each controlled comparison."}], "dissipation": [{"id": "compare", "title": "Explain the evidence", "kind": "dissipation", "type": "compare", "cases": [["0", "A closed system has…", ["No net energy transfer across its boundary", "No internal energy changes", "No thermal stores"], 0, "Internal redistribution can occur with constant total."], ["1", "Dissipated energy is…", ["Destroyed permanently", "Stored in less useful ways", "Always converted into massless nothing"], 1, "Wasted is a judgement about usefulness."], ["2", "100 J input with 60 J useful leaves…", ["160 J destroyed", "60 J missing", "40 J in other stores"], 2, "100−60=40; total remains 100."]]}, {"id": "calculate", "title": "Calculate with units", "kind": "dissipation-data", "type": "numeric", "prompt": "Fresh account:250 J input and 175 J useful. Calculate unwanted transfer.", "answer": 75, "unit": "J", "reasonChoices": ["250−175", "250+175", "175÷250"], "reason": 0, "why": "Check the equation, order and supplied units."}, {"id": "model", "title": "Predict and compare the model", "kind": "dissipation-model", "type": "experiment", "experiment": "dissipation", "why": "Predict from the stated quantities; record each controlled comparison."}], "insulation": [{"id": "compare", "title": "Explain the evidence", "kind": "insulation", "type": "compare", "cases": [["0", "Under equal conditions, higher conductivity produces…", ["Faster energy transfer by conduction", "No energy transfer", "Slower conduction by definition"], 0, "Compare the rate with other factors held constant."], ["1", "A thicker wall of the same material usually makes conduction…", ["Faster without limit", "Slower for equal area and temperature difference", "Create energy inside the wall"], 1, "Thickness reduces conduction rate under comparable conditions."], ["2", "For a fair material comparison keep…", ["Every variable changing together", "Only the colour of the results table fixed", "Thickness, starting temperature, area and mass controlled"], 2, "Control alternatives that could affect cooling."]]}, {"id": "calculate", "title": "Calculate with units", "kind": "insulation-data", "type": "numeric", "prompt": "The sample cools from 80°C to 62°C. Calculate its temperature drop.", "answer": 18, "unit": "°C", "reasonChoices": ["80−62", "80+62", "62−80"], "reason": 0, "why": "Check the equation, order and supplied units."}, {"id": "model", "title": "Predict and compare the model", "kind": "insulation-model", "type": "experiment", "experiment": "insulation", "why": "Predict from the stated quantities; record each controlled comparison."}], "efficiency": [{"id": "compare", "title": "Explain the evidence", "kind": "efficiency", "type": "compare", "cases": [["0", "Efficiency is…", ["Useful output divided by total input", "Total input divided by useful output", "Useful output plus all input"], 0, "Use the intended useful transfer as numerator."], ["1", "60 J useful from 100 J input is…", ["60 J/s", "0.60 or 60%", "1.67 or 167%"], 1, "Efficiency is a unitless ratio."], ["2", "150 W useful from 200 W input gives…", ["50 W efficiency", "133%", "75%"], 2, "Use the power ratio with matching units."]]}, {"id": "calculate", "title": "Calculate with units", "kind": "efficiency-data", "type": "numeric", "prompt": "Fresh device input 400 J, useful 300 J. Calculate percentage efficiency.", "answer": 75, "unit": "%", "reasonChoices": ["300÷400×100", "400÷300×100", "400−300"], "reason": 0, "why": "Check the equation, order and supplied units."}, {"id": "model", "title": "Predict and compare the model", "kind": "efficiency-model", "type": "experiment", "experiment": "efficiency", "why": "Predict from the stated quantities; record each controlled comparison."}, {"id": "improve", "title": "Improve the intended transfer · Higher", "kind": "efficiency", "type": "compare", "higher": true, "cases": [["motor", "A lifting motor loses energy through friction. Choose a relevant change.", ["Suitable lubrication", "Create extra energy", "Warm the bearings more"], 0, "Reduce the unwanted frictional thermal pathway."], ["vessel", "A hot-water vessel loses useful thermal energy. Choose a relevant change.", ["Remove every wall", "Suitable insulation", "Increase conductivity"], 1, "Reduce unwanted transfer from the warm water."], ["purpose", "Insulating equipment that needs cooling is…", ["Always the best improvement", "Guaranteed to increase every efficiency", "A choice that must be checked against its purpose"], 2, "A useful intervention depends on the intended transfer."]]}], "resources": [{"id": "compare", "title": "Explain the evidence", "kind": "resources", "type": "compare", "cases": [["0", "Which set is entirely non-renewable?", ["Coal, oil, gas and nuclear fuel", "Wind, sunlight and tides", "Hydro, waves and biofuel"], 0, "Fuels in the first set are finite on useful human timescales."], ["1", "Renewable means…", ["Always available at full rated output", "Replenished as it is used or on a useful timescale", "Unable to cause environmental harm"], 1, "Availability and impact are separate questions."], ["2", "Tidal generation is…", ["Always at maximum output", "Dependent on whether it is sunny", "Predictable in timing but variable through the cycle"], 2, "Predictable does not mean continuous maximum output."]]}, {"id": "calculate", "title": "Calculate with units", "kind": "resources-data", "type": "numeric", "prompt": "Fresh fictional demand 30 units and wind output 18. Calculate backup required.", "answer": 12, "unit": "units", "reasonChoices": ["30−18", "30+18", "18÷30"], "reason": 0, "why": "Check the equation, order and supplied units."}, {"id": "model", "title": "Predict and compare the model", "kind": "resources-model", "type": "experiment", "experiment": "resources", "why": "Predict from the stated quantities; record each controlled comparison."}]};
export const tasksForPhy2=(k,tier='Higher')=>phy2Tasks[k].filter(t=>!t.higher||tier==='Higher');
export const validPhy2=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericPhy2=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advancePhy2=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
export const experimentOptions={power:{a:[['120','120 J work'],['240','240 J work']],b:[['2','2 s'],['4','4 s']],labels:['Equal-work comparison','Duration'],unit:'W power'},dissipation:{a:[['100','100 J input'],['200','200 J input']],b:[['0.25','25% dissipated'],['0.4','40% dissipated']],labels:['Input energy','Unwanted fraction'],unit:'J dissipated'},insulation:{a:[['1','Lower conductivity index1'],['2','Higher conductivity index2']],b:[['1','Thickness index1'],['2','Thickness index2']],labels:['Material model','Thickness model'],unit:'°C drop after10 model min'},efficiency:{a:[['100','100 J input'],['200','200 J input']],b:[['0.6','60% useful'],['0.8','80% useful']],labels:['Input energy','Useful fraction'],unit:'J useful'},resources:{a:[['20','Wind capacity20 units'],['40','Wind capacity40 units']],b:[['calm','Calm:10% of capacity'],['windy','Windy:75% of capacity']],labels:['Installed capacity','Supplied weather snapshot'],unit:'backup units'}};
export function power(E,t){if(!Number.isFinite(E)||E<0||!Number.isFinite(t)||t<=0)throw new RangeError('Non-negative energy and positive time required.');return E/t;}
export function allocation(input,fraction){if(!Number.isFinite(input)||input<=0||!Number.isFinite(fraction)||fraction<0||fraction>1)throw new RangeError('Positive input and fraction0–1 required.');return{input,useful:input*fraction,waste:input*(1-fraction)};}
export function cooling(k,d,t=10){if(![1,2].includes(k)||![1,2].includes(d)||!Number.isFinite(t)||t<0)throw new RangeError('Use the stated model indices and non-negative time.');let initial=80,ambient=20,final=ambient+(initial-ambient)*Math.exp(-.04*k*t/d);return{initial,ambient,final,drop:initial-final,k,d,t};}
export function resourceBalance(capacity,weather){if(![20,40].includes(capacity)||!['calm','windy'].includes(weather))throw new RangeError('Choose stated capacity/weather.');let demand=30,fraction=weather==='calm'?.1:.75,wind=capacity*fraction,used=Math.min(demand,wind);return{capacity,weather,fraction,demand,wind,used,backup:demand-used,surplus:wind-used};}
export function experimentResult(k,a,b){let o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated model settings.');if(k==='power')return{E:+a,t:+b,value:power(+a,+b)};if(k==='dissipation'){let r=allocation(+a,1-Number(b));return{...r,value:r.waste};}if(k==='insulation'){let r=cooling(+a,+b);return{...r,value:r.drop};}if(k==='efficiency'){let r=allocation(+a,+b);return{...r,efficiency:Number(b),value:r.useful};}let r=resourceBalance(+a,b);return{...r,value:r.backup};}
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
